import 'dart:io';
import 'dart:math' as math;
import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:flutter_test/flutter_test.dart';

/// Why: launcher and splash deliberately use separate layers: the launcher
/// background stays white while the system splash selects white/black by theme
/// and draws only the transparent foreground mark. These are binary/resource
/// contracts, so ordinary widget tests cannot see them — this file decodes the
/// shipped PNGs and checks geometry and the colours the build packages.
///
/// The PNGs are generated by `tool/branding/build_icons.py` from
/// `assets/branding/vanne_mark.png` and `vanne_monochrome.png`. Run
/// `python3 tool/branding/build_icons.py --check` in CI to prove they are not
/// stale.
const _res = 'android/app/src/main/res';

const _densities = <String, double>{
  'mdpi': 1,
  'hdpi': 1.5,
  'xhdpi': 2,
  'xxhdpi': 3,
  'xxxhdpi': 4,
};

const _canvasDp = 108;
const _markDp = 48;
const _legacyDp = 48;

const _lightArgb = '#FFFFFFFF';

String _read(String path) {
  final file = File(path);
  expect(file.existsSync(), isTrue, reason: '$path must exist');
  return file.readAsStringSync();
}

String _color(String path, String name) {
  final match = RegExp(
    '<color\\s+name="$name"\\s*>\\s*(#[0-9A-Fa-f]{8})\\s*</color>',
  ).firstMatch(_read(path));
  expect(match, isNotNull, reason: '$path must define $name');
  return match!.group(1)!.toUpperCase();
}

/// Decoded RGBA pixels of a shipped asset.
final class _Pixels {
  _Pixels(this.width, this.height, this.rgba);

  final int width;
  final int height;
  final Uint8List rgba;

  int red(int x, int y) => rgba[(y * width + x) * 4];
  int green(int x, int y) => rgba[(y * width + x) * 4 + 1];
  int blue(int x, int y) => rgba[(y * width + x) * 4 + 2];
  int alpha(int x, int y) => rgba[(y * width + x) * 4 + 3];

  /// Bounding box of pixels with non-zero alpha.
  ({int left, int top, int width, int height}) alphaBounds() {
    var left = width, top = height, right = -1, bottom = -1;
    for (var y = 0; y < height; y++) {
      for (var x = 0; x < width; x++) {
        if (alpha(x, y) == 0) continue;
        if (x < left) left = x;
        if (x > right) right = x;
        if (y < top) top = y;
        if (y > bottom) bottom = y;
      }
    }
    expect(
      right,
      greaterThanOrEqualTo(0),
      reason: 'asset is fully transparent',
    );
    return (
      left: left,
      top: top,
      width: right - left + 1,
      height: bottom - top + 1,
    );
  }

  /// Bounding box of pixels that differ from [background].
  ({int left, int top, int width, int height}) contentBounds(
    (int, int, int) background,
  ) {
    var left = width, top = height, right = -1, bottom = -1;
    for (var y = 0; y < height; y++) {
      for (var x = 0; x < width; x++) {
        final differs =
            alpha(x, y) < 250 ||
            (red(x, y), green(x, y), blue(x, y)) != background;
        if (!differs) continue;
        if (x < left) left = x;
        if (x > right) right = x;
        if (y < top) top = y;
        if (y > bottom) bottom = y;
      }
    }
    expect(right, greaterThanOrEqualTo(0), reason: 'asset has no mark');
    return (
      left: left,
      top: top,
      width: right - left + 1,
      height: bottom - top + 1,
    );
  }
}

Future<_Pixels> _decode(String path) async {
  final file = File(path);
  expect(file.existsSync(), isTrue, reason: '$path must exist');
  final codec = await ui.instantiateImageCodec(file.readAsBytesSync());
  final frame = await codec.getNextFrame();
  final data = await frame.image.toByteData(format: ui.ImageByteFormat.rawRgba);
  expect(data, isNotNull, reason: 'could not read pixels of $path');
  final pixels = _Pixels(
    frame.image.width,
    frame.image.height,
    data!.buffer.asUint8List(),
  );
  frame.image.dispose();
  codec.dispose();
  return pixels;
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  test('adaptive icon wiring supports API 26 and API 33', () {
    for (final version in ['mipmap-anydpi-v26', 'mipmap-anydpi-v33']) {
      final xml = _read('$_res/$version/ic_launcher.xml');
      expect(
        xml,
        contains('@color/ic_launcher_background'),
        reason: '$version must use the fixed white launcher background',
      );
      expect(
        xml,
        contains('@drawable/ic_launcher_foreground'),
        reason: '$version must use the app mark',
      );
    }
    // Pre-33 parsers must never see <monochrome>.
    expect(
      _read('$_res/mipmap-anydpi-v26/ic_launcher.xml'),
      isNot(contains('<monochrome')),
    );
    expect(
      _read('$_res/mipmap-anydpi-v33/ic_launcher.xml'),
      contains(
        '<monochrome android:drawable="@drawable/ic_launcher_monochrome"',
      ),
    );
    expect(
      _read('android/app/src/main/AndroidManifest.xml'),
      contains('android:icon="@mipmap/ic_launcher"'),
    );
  });

  group('launcher background is fixed white', () {
    test('normal launcher background is pure white in every theme', () {
      expect(
        _color('$_res/values/colors.xml', 'ic_launcher_background'),
        _lightArgb,
      );
      expect(File('$_res/values-night/colors.xml').existsSync(), isFalse);
    });
  });

  group('adaptive mark geometry', () {
    test('marks stay centered and unclipped at every density', () async {
      for (final entry in _densities.entries) {
        final name = entry.key;
        final density = entry.value;
        final canvas = (_canvasDp * density).round();
        final target = (_markDp * density).round();
        for (final layer in [
          'ic_launcher_foreground',
          'ic_launcher_monochrome',
        ]) {
          final path = '$_res/drawable-$name/$layer.png';
          final pixels = await _decode(path);
          expect(pixels.width, canvas, reason: '$path canvas');
          expect(pixels.height, canvas, reason: '$path canvas');

          final bounds = pixels.alphaBounds();
          expect(
            bounds.height,
            closeTo(target, 1),
            reason: '$path mark height must be ${_markDp}dp',
          );
          expect(bounds.width / bounds.height, closeTo(206 / 208, 0.02));

          final leftGap = bounds.left;
          final rightGap = pixels.width - (bounds.left + bounds.width);
          final topGap = bounds.top;
          final bottomGap = pixels.height - (bounds.top + bounds.height);
          expect(
            leftGap,
            closeTo(rightGap, 1),
            reason: '$path horizontal centring',
          );
          expect(
            topGap,
            closeTo(bottomGap, 1),
            reason: '$path vertical centring',
          );

          final halfDiagonal =
              math.sqrt(
                bounds.width * bounds.width + bounds.height * bounds.height,
              ) /
              2;
          expect(
            halfDiagonal,
            lessThanOrEqualTo(_canvasDp * 72 / 108 / 2 * density + 0.01),
            reason: '$path mark must fit the visible circle',
          );
        }
      }
    });

    test('themed (monochrome) mask is a single-colour silhouette', () async {
      final pixels = await _decode(
        '$_res/drawable-xxxhdpi/ic_launcher_monochrome.png',
      );
      final bounds = pixels.alphaBounds();
      var samples = 0;
      for (var y = bounds.top; y < bounds.top + bounds.height; y += 4) {
        for (var x = bounds.left; x < bounds.left + bounds.width; x += 4) {
          if (pixels.alpha(x, y) < 250) continue;
          expect(pixels.red(x, y), pixels.green(x, y));
          expect(pixels.green(x, y), pixels.blue(x, y));
          samples++;
        }
      }
      expect(samples, greaterThan(100), reason: 'mask must have a real mark');
    });
  });

  test('legacy bitmaps keep an opaque white field at every density', () async {
    for (final entry in _densities.entries) {
      final name = entry.key;
      final density = entry.value;
      final size = (_legacyDp * density).round();
      final mark = (_legacyDp * _markDp / _canvasDp * density).round();
      final path = '$_res/mipmap-$name/ic_launcher.png';
      final pixels = await _decode(path);
      expect(pixels.width, size, reason: '$path width');
      expect(pixels.height, size, reason: '$path height');
      // Legacy launchers show the full square, so the field must be opaque.
      expect(pixels.alpha(0, 0), 255, reason: '$path opacity');
      expect(
        (pixels.red(0, 0), pixels.green(0, 0), pixels.blue(0, 0)),
        (255, 255, 255),
        reason: '$path background',
      );
      final bounds = pixels.contentBounds((255, 255, 255));
      expect(bounds.height, closeTo(mark, 1), reason: '$path mark size');
      expect(bounds.width / bounds.height, closeTo(206 / 208, 0.02));
      expect(
        bounds.left,
        closeTo(size - (bounds.left + bounds.width), 1),
        reason: '$path horizontal centring',
      );
    }
  });

  test('no night-qualified legacy bitmap shadows the adaptive icon', () {
    // Qualifiers are matched by precedence, and `night` outranks `anydpi`.
    // A `mipmap-night-*/ic_launcher.png` would replace the adaptive icon XML
    // in dark mode, bypassing its fixed-white background and monochrome layer.
    final shadowing = Directory(_res)
        .listSync()
        .whereType<Directory>()
        .where((dir) => dir.path.contains('mipmap-night'))
        .toList();
    expect(shadowing, isEmpty);
  });

  group('generation inputs', () {
    test('shipped PNGs match the checked-in masters', () {
      // These inputs are prerequisites for a real generator invocation, not
      // independent existence-only contracts.
      expect(File('assets/branding/vanne_mark.png').existsSync(), isTrue);
      expect(File('assets/branding/vanne_monochrome.png').existsSync(), isTrue);
      expect(File('tool/branding/build_icons.py').existsSync(), isTrue);
      expect(
        _read('tool/apply_android_overrides.sh'),
        contains('tool/branding/build_icons.py'),
        reason: 'the Android regeneration path must rebuild launcher icons',
      );

      // The generator is the source of truth; `--check` fails when a PNG was
      // edited by hand or the masters changed without regenerating. Skipped
      // only when python3 is unavailable (the generator is stdlib-only).
      final ProcessResult result;
      try {
        result = Process.runSync('python3', [
          'tool/branding/build_icons.py',
          '--check',
        ]);
      } on ProcessException catch (error) {
        stderr.writeln(
          'Skipping icon staleness check: python3 not available ($error)',
        );
        return;
      }
      expect(result.exitCode, 0, reason: '${result.stdout}${result.stderr}');
    });

    test('regeneration templates mirror the adaptive icon XML', () {
      // `flutter create` restores the stock Flutter adaptive icon. The override
      // script copies these templates back before regenerating the PNGs; if
      // they drift, a regenerated android/ folder silently loses the icon.
      for (final rel in [
        'mipmap-anydpi-v26/ic_launcher.xml',
        'mipmap-anydpi-v33/ic_launcher.xml',
        'values/colors.xml',
      ]) {
        expect(
          _read('tool/android_overrides/res/$rel'),
          _read('$_res/$rel'),
          reason: 'template copy of $rel must match the live resource',
        );
      }
    });
  });
}
